public class Driver { sealed interface Employee permits FullTime,PartTime,Intern{double pay();String details();}record FullTime(String n,String id,double salary)implements Employee{public double pay(){return salary;}public String details(){return id+" - "+n;}}record PartTime(String n,String id,double h,double r)implements Employee{public double pay(){return h*r;}public String details(){return id+" - "+n;}}record Intern(String n,String id,double stipend)implements Employee{public double pay(){return stipend;}public String details(){return id+" - "+n;}}public static void main(String[]a){Employee[] e={new FullTime("Manav","E101",75000),new PartTime("Karan","E102",40,500),new Intern("Rohan","E103",15000)};double total=0;for(Employee x:e){total+=x.pay();System.out.printf("%s | Salary: Rs. %.2f%s%n",x.details(),x.pay(),x instanceof Intern?" [Academic Internship]":"");}System.out.printf("Total Monthly Payroll: Rs. %.2f%n",total);}}
